/** A bounded batch independent of the live VPN. Every temporary engine is closed in finally. */
final class ProbeManager {
 static final ProbeManager INSTANCE=new ProbeManager();private final ExecutorService coordinator=Executors.newSingleThreadExecutor();volatile Batch current;volatile Network resultNetwork;volatile String error="";
 static final class Batch {final Map<String,String> errors=new ConcurrentHashMap<>();final Set<String> pending=ConcurrentHashMap.newKeySet();final int total;final AtomicInteger completed=new AtomicInteger();final AtomicBoolean canceled=new AtomicBoolean();final Network network;volatile BoxService box;volatile XrayProcesses processes;volatile ExecutorService workers;Batch(int total,Network n){this.total=total;network=n;}}
 boolean running(){return current!=null;}boolean pending(String id){Batch b=current;return b!=null&&b.pending.contains(id);}String progress(){Batch b=current;return b==null?"":b.completed.get()+"/"+b.total;}
 synchronized void checkNetwork(Context c){Network next=physical(c);if(resultNetwork!=null&&!resultNetwork.equals(next)){cancel();TunnelService.pings.clear();resultNetwork=next;}}
 synchronized void cancel(){Batch b=current;if(b==null)return;b.canceled.set(true);if(b.workers!=null)b.workers.shutdownNow();}
 static Network physical(Context context){ConnectivityManager cm=context.getSystemService(ConnectivityManager.class);Network best=null;int score=-1;for(Network n:cm.getAllNetworks()){NetworkCapabilities c=cm.getNetworkCapabilities(n);if(c==null||c.hasTransport(NetworkCapabilities.TRANSPORT_VPN)||!c.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET))continue;int s=(c.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)?100:0)+(c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?20:10);if(s>score){score=s;best=n;}}return best;}
 synchronized void start(Context context,JSONArray source)throws Exception{
  if(current!=null){cancel();return;}if(source.length()==0)return;Context c=context.getApplicationContext();Network n=physical(c);if(n==null)throw new IOException(L10n.s(R.string.msg_f0a50c59fc));JSONArray nodes=new JSONArray(source.toString());Batch b=new Batch(nodes.length(),n);for(int i=0;i<nodes.length();i++){String id=nodes.getJSONObject(i).getString("id");b.pending.add(id);TunnelService.pings.remove(id);}error="";resultNetwork=n;current=b;coordinator.execute(()->run(c,b,nodes));
 }
 void run(Context c,Batch b,JSONArray nodes){List<ServerSocket> held=new ArrayList<>();try{
  if(b.canceled.get())return;String first=nodes.getJSONObject(0).getString("id"),password=UUID.randomUUID().toString();Map<String,Integer> ports=new HashMap<>();for(int i=0;i<nodes.length();i++){String id=nodes.getJSONObject(i).getString("id");ServerSocket ss=new ServerSocket(0,0,InetAddress.getLoopbackAddress());held.add(ss);ports.put(id,ss.getLocalPort());}
  JSONObject data=obj("servers",nodes,"rules",new JSONArray(),"wifi",first,"cellular",first,"auto",true,"defaultTarget","direct");Configuration.Result built=Configuration.build(data,"wifi",ports,password);JSONObject config=new JSONObject(built.singbox);config.put("inbounds",new JSONArray());config.remove("experimental");config.put("dns",obj("servers",arr(obj("tag","local","address","local","detour","direct")),"final","local","strategy","prefer_ipv4"));config.put("route",obj("final",first,"auto_detect_interface",true,"default_domain_resolver","local"));
  SetupOptions setup=new SetupOptions();setup.setBasePath(c.getFilesDir().getPath());setup.setWorkingPath(c.getFilesDir().getPath());setup.setTempPath(c.getCacheDir().getPath());setup.setFixAndroidStack(true);Libbox.setup(setup);Libbox.setMemoryLimit(true);
  for(ServerSocket ss:held)ss.close();held.clear();Map<String,String> definitions=new LinkedHashMap<>(built.groups);if(built.xray!=null)definitions.put("__single",built.xray);b.processes=new XrayProcesses(c,definitions);b.processes.ensure("__single");b.box=Libbox.newService(config.toString(),new ProbePlatform(c,b.network));b.box.start();
  b.workers=Executors.newFixedThreadPool(4);List<Future<?>> jobs=new ArrayList<>();for(int i=0;i<nodes.length();i++){String id=nodes.getJSONObject(i).getString("id");jobs.add(b.workers.submit(()->{int ping=-1;try{if(b.canceled.get())return;if(!b.network.equals(physical(c)))throw new IOException("Network changed");b.processes.ensure(id);long deadline=System.currentTimeMillis()+8000;while(!b.canceled.get()){long left=deadline-System.currentTimeMillis();if(left<=0)break;try{ping=b.box.mobileDelayFor(id,(int)Math.min(6000,left));b.errors.remove(id);break;}catch(Exception e){b.errors.put(id,TunnelService.safeError(e));if(!built.groups.containsKey(id)||System.currentTimeMillis()>=deadline)throw e;Thread.sleep(150);}}}catch(Exception problem){b.errors.put(id,TunnelService.safeError(problem));}finally{if(!b.canceled.get()&&b.network.equals(physical(c)))TunnelService.pings.put(id,ping);b.pending.remove(id);b.completed.incrementAndGet();b.processes.release(id);}}));}
  b.workers.shutdown();while(!b.workers.awaitTermination(200,TimeUnit.MILLISECONDS)){if(b.canceled.get()||!b.network.equals(physical(c))){b.canceled.set(true);b.workers.shutdownNow();break;}}
 }catch(Exception e){if(!b.canceled.get())error=TunnelService.safeError(e);}finally{
  if(b.workers!=null)b.workers.shutdownNow();if(b.box!=null)try{b.box.close();}catch(Exception ignored){}if(b.processes!=null)b.processes.close();for(ServerSocket ss:held)try{ss.close();}catch(Exception ignored){}b.pending.clear();synchronized(this){if(current==b)current=null;}
 }}
}
